{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Mithramycin, a large glycosylated polycyclic antitumor antibiotic, showed a peak CSF:plasma ratio of only 0.12 in monkeys and little brain distribution, indicating poor CNS access for this class of large glycosylated polycyclic natural products; this transfers to the query's anthracycline-aminosugar scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Digitoxin, a cardiac glycoside with multiple sugar residues, had a very low CSF/plasma ratio (0.01-0.03) in dogs, supporting poor BBB penetration for large glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "SC-4453, a cardiac glycoside, had the lowest brain concentration among tissues at steady state in guinea pigs, demonstrating a blood-brain barrier to this glycoside class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "CMT-3, a lipophilic tetracycline, accumulated in rat brain (4 µg/g) and was labeled permeable, providing a contradictory example that some large polycyclic antibiotics can achieve brain exposure; however, its lower structural similarity and different scaffold reduce transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C05"],
      "claim": "Hesperidin, a flavonoid glycoside, was detected in mouse brain after oral administration, showing that some glycosylated polyphenols can cross the BBB; however, flavonoid disposition differs substantially from anthracycline-aminosugar chemistry.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Prediction: fail. The query is daunorubicin, an anthracycline with an aminosugar; direct evidence from related glycosylated polycyclic antibiotics (mithramycin) and cardiac glycosides (digitoxin, SC-4453) shows poor CNS exposure, and the high-MW/high-TPSA/ionized/efflux-prone profile supports inadequate BBB access. Contradictory brain-penetrant glycoside examples are structurally distant and do not overcome the anthracycline P-gp liability.",
  "evidence_gaps": [
    "No direct experimental CNS exposure data for daunorubicin itself in the provided evidence set.",
    "Most evidence molecules have low Morgan similarity (<0.25) to the query.",
    "No human CSF or brain uptake data for the query.",
    "Efflux transporter contribution is inferred but not directly measured for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

